".join( json.dumps({"custom_id": f"req-{i}", "method": "POST", "url": "/v1/chat/completions", "body": {"model": "gpt-5", "max_completion_tokens": 16, "messages": [{"role": "user", "content": f"Ignore this filler: {pad}
